void Game::run() {
#ifdef _WIN32
  SetConsoleOutputCP(65001);
#endif
  while (true) {
    showMenu();
    int choice;
    cout << "请输入选项：";
    if (!(cin >> choice)) {
      cin.clear();
      cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }
    switch (choice) {
    case 1:
      startNewGame();
      break;
    case 2:
      loadGame("saveGame.txt");
      gameLoop(humanColor);
      break;
    case 3:
      cout << "Goodbye!" << endl;
      return;
    default:
      cout << "无效选项！" << endl;
      continue;
    }
  }
}

